class TestServiceConstructor:
    def test_max_title_length_must_be_positive(self):
        with pytest.raises(ValueError, match="positive"):
            TaskService(InMemoryTaskRepository(), max_title_length=0)

    def test_default_now(self):
        svc = TaskService(InMemoryTaskRepository())
        t = svc.create("Hello")
        assert t.created_at is not None


# ── create ────────────────────────────────────────────────────────────────────

class TestCreate:
    def test_basic_create(self, svc):
        task = svc.create("Buy milk")
        assert task.id == 1
        assert task.title == "Buy milk"
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.created_at == NOW

    def test_create_with_priority(self, svc):
        task = svc.create("Urgent", priority=TaskPriority.HIGH)
        assert task.priority == TaskPriority.HIGH

    def test_create_with_due_at(self, svc):
        due = NOW + timedelta(days=7)
        task = svc.create("Later", due_at=due)
        assert task.due_at == due

    def test_create_with_tags(self, svc):
        task = svc.create("Tagged", tags=["work", "home"])
        assert len(task.tags) == 2

    def test_create_strips_title(self, svc):
        task = svc.create("  padded  ")
        assert task.title == "padded"

    def test_create_deduplicates_tags(self, svc):
        task = svc.create("T", tags=["work", "WORK"])
        assert len(task.tags) == 1

    def test_title_not_string(self, svc):
        with pytest.raises(ValueError, match="string"):
            svc.create(123)  # type: ignore

    def test_title_empty(self, svc):
        with pytest.raises(ValueError, match="empty"):
            svc.create("")

    def test_title_whitespace(self, svc):
        with pytest.raises(ValueError, match="empty"):
            svc.create("   ")

    def test_title_too_long(self, svc):
        with pytest.raises(ValueError, match="200 characters"):
            svc.create("x" * 201)

    def test_custom_max_title(self, repo):
        svc = TaskService(repo, max_title_length=5)
        with pytest.raises(ValueError, match="5 characters"):
            svc.create("toolong")

    def test_bad_priority(self, svc):
        with pytest.raises(ValueError, match="TaskPriority"):
            svc.create("T", priority="high")  # type: ignore

    def test_due_at_naive(self, svc):
        with pytest.raises(ValueError, match="timezone-aware"):
            svc.create("T", due_at=datetime(2025, 1, 1))

    def test_due_at_non_datetime(self, svc):
        with pytest.raises(ValueError, match="datetime"):
            svc.create("T", due_at="2025-01-01")  # type: ignore

    def test_due_at_converted_to_utc(self, svc):
        eastern = timezone(timedelta(hours=-5))
        due = datetime(2025, 6, 20, 12, 0, 0, tzinfo=eastern)
        task = svc.create("T", due_at=due)
        assert task.due_at.tzinfo == timezone.utc

    def test_increments_ids(self, svc):
        t1 = svc.create("A")
        t2 = svc.create("B")
        assert t2.id == t1.id + 1


# ── get ───────────────────────────────────────────────────────────────────────

class TestGet:
    def test_get_existing(self, svc):
        created = svc.create("Test")
        assert svc.get(created.id).title == "Test"

    def test_get_missing(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.get(999)


# ── list / query ──────────────────────────────────────────────────────────────

class TestListAndQuery:
    def test_list_all(self, svc):
        svc.create("A")
        svc.create("B")
        assert len(svc.list_all()) == 2

    def test_list_all_empty(self, svc):
        assert svc.list_all() == []

    def test_query_delegates(self, svc):
        from tasks_api.queries import TaskQuery
        svc.create("Alpha")
        svc.create("Beta")
        page = svc.query(TaskQuery(search="alpha"))
        assert page.total == 1


# ── complete / reopen ─────────────────────────────────────────────────────────

class TestCompleteReopen:
    def test_complete(self, svc):
        t = svc.create("Do it")
        done = svc.complete(t.id)
        assert done.status == TaskStatus.DONE
        assert done.completed_at == NOW

    def test_complete_already_done(self, svc):
        t = svc.create("Do it")
        svc.complete(t.id)
        with pytest.raises(ValueError, match="already done"):
            svc.complete(t.id)

    def test_complete_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.complete(999)

    def test_reopen(self, svc):
        t = svc.create("Do it")
        svc.complete(t.id)
        reopened = svc.reopen(t.id)
        assert reopened.status == TaskStatus.PENDING
        assert reopened.completed_at is None

    def test_reopen_already_pending(self, svc):
        t = svc.create("Pending")
        with pytest.raises(ValueError, match="already pending"):
            svc.reopen(t.id)

    def test_reopen_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.reopen(999)


# ── delete ────────────────────────────────────────────────────────────────────

class TestDelete:
    def test_delete_existing(self, svc):
        t = svc.create("Bye")
        svc.delete(t.id)
        with pytest.raises(TaskNotFoundError):
            svc.get(t.id)

    def test_delete_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.delete(999)


# ── set_priority / set_due_at ─────────────────────────────────────────────────

class TestMutations:
    def test_set_priority(self, svc):
        t = svc.create("T")
        updated = svc.set_priority(t.id, TaskPriority.HIGH)
        assert updated.priority == TaskPriority.HIGH

    def test_set_priority_invalid(self, svc):
        t = svc.create("T")
        with pytest.raises(ValueError, match="TaskPriority"):
            svc.set_priority(t.id, "high")  # type: ignore

    def test_set_priority_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.set_priority(999, TaskPriority.LOW)

    def test_set_due_at(self, svc):
        t = svc.create("T")
        due = NOW + timedelta(days=10)
        updated = svc.set_due_at(t.id, due)
        assert updated.due_at == due

    def test_set_due_at_none(self, svc):
        t = svc.create("T", due_at=NOW + timedelta(days=1))
        updated = svc.set_due_at(t.id, None)
        assert updated.due_at is None

    def test_set_due_at_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.set_due_at(999, NOW)


# ── tags ──────────────────────────────────────────────────────────────────────

class TestTagOperations:
    def test_add_tags(self, svc):
        t = svc.create("T", tags=["a"])
        updated = svc.add_tags(t.id, ["b", "c"])
        names = {tg.name for tg in updated.tags}
        assert names == {"a", "b", "c"}

    def test_add_duplicate_tag(self, svc):
        t = svc.create("T", tags=["a"])
        updated = svc.add_tags(t.id, ["a", "A"])
        assert len(updated.tags) == 1

    def test_add_tags_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.add_tags(999, ["x"])

    def test_remove_tag(self, svc):
        t = svc.create("T", tags=["a", "b"])
        updated = svc.remove_tag(t.id, "a")
        assert [tg.name for tg in updated.tags] == ["b"]

    def test_remove_tag_not_attached(self, svc):
        t = svc.create("T", tags=["a"])
        with pytest.raises(ValueError, match="not attached"):
            svc.remove_tag(t.id, "z")

    def test_remove_tag_not_found(self, svc):
        with pytest.raises(TaskNotFoundError):
            svc.remove_tag(999, "a")

