"""Tests for tasks_api.repository — InMemoryTaskRepository + normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, id: int, title: str = "Test") -> Task:
        return Task(id=id, title=title)

    def test_add_and_get(self, repo):
        t = self._make_task(1)
        repo.add(t)
        assert repo.get(1) is t

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(self._make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make_task(1, title="Dup"))

    def test_list_returns_snapshot(self, repo):
        repo.add(self._make_task(1))
        repo.add(self._make_task(2))
        items = list(repo.list())
        assert len(items) == 2

    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_update_existing(self, repo):
        t = self._make_task(1, title="Old")
        repo.add(t)
        t.title = "New"
        repo.update(t)
        assert repo.get(1).title == "New"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make_task(99))

    def test_delete_existing(self, repo):
        repo.add(self._make_task(1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(42) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_strings_become_tags(self):
        result = normalize_tags(["Work", "home"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["work", "home"]

    def test_deduplicates(self):
        result = normalize_tags(["work", "WORK", "  work  "])
        assert len(result) == 1
        assert result[0].name == "work"

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["b", "a", "c", "a"])
        assert [t.name for t in result] == ["b", "a", "c"]

    def test_mixed_tags_and_strings(self):
        result = normalize_tags([Tag("alpha"), "beta", Tag("alpha")])
        assert len(result) == 2
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_empty_iterable(self):
        assert normalize_tags([]) == []

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            normalize_tags(["valid", "bad tag!"])

